import type { MediaOptions, GalleryItem } from "./types";
import { Alert, Badge, Button, Card, Group, Image, Loader, SimpleGrid, Stack, Text, UnstyledButton } from "@mantine/core";
import { useWidgetHost, useWidgetOptions, useWidgetQuery, useWidgetServices, useWidgetState } from "@homarr/widget-sdk";
import Sessions from "./sessions";
export default function MediaWall() {
  const host = useWidgetHost(); const options = useWidgetOptions<MediaOptions>(); const services = useWidgetServices();
  const [selected,setSelected] = useWidgetState<GalleryItem|null>("selectedImage",null);
  const gallery = useWidgetQuery<{items:GalleryItem[];errors:string[];configured:boolean}>("gallery",{}, {refetchInterval:60000});
  const columns = Math.max(1,Math.floor(host.visibleWidth/220));
  return <Stack p="sm" h="100%" gap="sm" style={{overflow:"auto"}}>
    <Group justify="space-between"><Text fw={600}>{options.title}</Text><Button size="compact-xs" variant="subtle" onClick={() => void gallery.refetch()}>Refresh gallery</Button></Group>
    {gallery.error && <Alert color="red">{gallery.error.message}</Alert>}
    {(gallery.data?.errors ?? []).map((error,index) => <Alert key={index} color="yellow">{error}</Alert>)}
    {host.displayMode === "advanced" && selected && <Card withBorder><Stack gap="xs"><Group justify="space-between"><Text fw={600}>{selected.name}</Text><Button size="compact-xs" variant="subtle" onClick={() => setSelected(null)}>Close image</Button></Group><Snapshot item={selected} large /></Stack></Card>}
    <SimpleGrid cols={columns}>{(gallery.data?.items ?? []).map((item) => <Card key={`${item.kind}:${item.id}`} withBorder p="xs"><UnstyledButton onClick={() => {setSelected(item);services.openAdvanced();}}><Stack gap={4}><Snapshot item={item} /><Group justify="space-between"><Text size="sm">{item.name}</Text><Badge size="xs" variant="light">{item.kind}</Badge></Group>{item.takenAt && <Text size="xs" c="dimmed">{new Date(item.takenAt).toLocaleDateString(host.locale)}</Text>}</Stack></UnstyledButton></Card>)}</SimpleGrid>
    {gallery.data && !gallery.data.configured && <Text size="sm" c="dimmed">Bind a camera or Immich connection to add authenticated images.</Text>}
    {gallery.data?.configured && !gallery.data.items.length && <Text size="sm" c="dimmed">No configured snapshots or matching Immich images.</Text>}
    {options.showSessions && <Sessions />}
  </Stack>;
}
function Snapshot({item,large=false}:{item:GalleryItem;large?:boolean}) {
  const options = useWidgetOptions<MediaOptions>();
  const image = useWidgetQuery<{dataUrl:string;updatedAt:string}>("image",{kind:item.kind,id:item.id},{refetchInterval:item.kind === "camera" ? Math.max(5,Number(options.snapshotInterval)||15)*1000 : 300000,staleTime:5000});
  if (image.isPending) return <Stack h={160} justify="center" align="center"><Loader size="sm" /></Stack>;
  if (image.error) return <Alert color="yellow">{image.error.message}</Alert>;
  return <Image src={image.data?.dataUrl} alt={item.name} h={large ? 420 : 160} fit={large ? "contain" : "cover"} radius="sm" />;
}

