import type { Camera, MediaOptions, GalleryItem, GalleryImageInput, ImmichAsset, MediaSessions } from "./types";
import { callWidgetIntegration, defineWidgetServer, fetchWidgetConnection, getWidgetServerContext } from "@homarr/widget-sdk/server";
const cameras = (options:MediaOptions):Camera[] => Array.isArray(options.cameras) ? options.cameras.slice(0,8).filter((item) => item && typeof item.name === "string" && typeof item.path === "string") : [];
export default defineWidgetServer({
  sessions: async (_input,context) => {
    const {bindingNames} = await getWidgetServerContext<MediaOptions>(context);
    if (!bindingNames.includes("media")) return {data:[],configured:false};
    return callWidgetIntegration<MediaSessions>(context,{connection:"media",capability:"media.sessions",input:{showOnlyPlaying:false}});
  },
  gallery: async (_input,context) => {
    const {bindingNames,options} = await getWidgetServerContext<MediaOptions>(context);
    const items:GalleryItem[] = []; const errors:string[] = [];
    if (bindingNames.includes("camera")) items.push(...cameras(options).map<GalleryItem>((camera,index) => ({kind:"camera",id:String(index),name:camera.name})));
    if (bindingNames.includes("immich")) {
      try {
        const response = await fetchWidgetConnection<{assets?:{items?:ImmichAsset[]}}>(context,{connection:"immich",path:"/api/search/metadata",method:"POST",body:{type:"IMAGE",size:Math.max(1,Math.min(12,Number(options.imageCount)||8))}});
        if (!response.ok) throw new Error(`Immich returned HTTP ${response.status}`);
        const assets = response.data?.assets?.items;
        if (!Array.isArray(assets)) throw new Error("Immich search returned an unexpected result");
        items.push(...assets.slice(0,12).map<GalleryItem>((asset) => ({kind:"immich",id:asset.id,name:asset.originalFileName ?? "Photo",takenAt:asset.localDateTime ?? asset.fileCreatedAt})));
      } catch (error) { errors.push(error instanceof Error ? error.message : String(error)); }
    }
    return {items,errors,configured:bindingNames.includes("camera") || bindingNames.includes("immich")};
  },
  image: async (input:GalleryImageInput,context) => {
    const {options,bindingNames} = await getWidgetServerContext<MediaOptions>(context);
    let path; let connection;
    if (input?.kind === "camera") {
      const camera = cameras(options).find((_camera,index) => String(index) === input.id);
      if (!camera) throw new Error("Choose a configured camera snapshot");
      path = camera.path; connection = "camera";
    } else if (input?.kind === "immich" && typeof input.id === "string" && /^[0-9a-f-]{36}$/i.test(input.id)) {
      path = `/api/assets/${encodeURIComponent(input.id)}/thumbnail?size=thumbnail`; connection = "immich";
    } else throw new Error("Unknown gallery image");
    if (!bindingNames.includes(connection)) throw new Error("The image connection is not bound");
    const response = await fetchWidgetConnection(context,{connection,path,responseType:"base64"});
    if (!response.ok) throw new Error(`Image returned HTTP ${response.status}. Check the configured endpoint and image permissions.`);
    const mime = response.contentType?.split(";")[0]?.trim().toLowerCase() ?? "";
    if (!["image/jpeg","image/png","image/webp","image/gif","image/avif"].includes(mime)) throw new Error("The endpoint must return a JPEG, PNG, WebP, GIF or AVIF snapshot");
    if (typeof response.data !== "string" || response.data.length > 900000) throw new Error("Use a smaller snapshot or thumbnail (under 675 KiB)");
    return {dataUrl:`data:${mime};base64,${response.data}`,updatedAt:response.updatedAt};
  },
});

