import type { MediaSessions } from "./types";
import { Alert, Badge, Button, Card, Group, Progress, SimpleGrid, Stack, Text } from "@mantine/core";
import { useWidgetHost, useWidgetQuery, useWidgetServices } from "@homarr/widget-sdk";
export default function Sessions() {
  const host = useWidgetHost();
  const services = useWidgetServices();
  const query = useWidgetQuery<MediaSessions>("sessions", {}, { refetchInterval: 10000 });
  const rows = query.data?.data ?? [];
  const columns = Math.max(1, Math.floor(host.visibleWidth / 240));
  return <Stack p="md"  style={{overflow:"auto"}}><Text fw={600}>Now playing · {rows.length}</Text>
    {query.error && <Alert color="red">{query.error.message}<Button variant="subtle" size="xs" onClick={() => void query.refetch()}>Retry</Button></Alert>}
    <SimpleGrid cols={columns}>{rows.map((session) => { const playing = session.currentlyPlaying; const playback = playing?.playback; return <Card key={session.sessionId} withBorder padding="sm"><Stack gap="xs"><Group justify="space-between"><Text size="sm" fw={600}>{session.user.username}</Text><Badge size="xs">{playback?.state ?? "idle"}</Badge></Group><Text>{playing?.name ?? session.sessionName}</Text>{playing?.episodeName && <Text size="xs" c="dimmed">{playing.episodeName}</Text>}{typeof playback?.durationMs === "number" && playback.durationMs > 0 && <Progress aria-label="Playback progress" value={100 * (playback.positionMs ?? 0) / playback.durationMs} />}<Button size="compact-xs" variant="light" onClick={() => services.openDetail({title: session.sessionName, content: <Stack><Text>{session.user.username}</Text><Text>{playing?.name}</Text><Text size="sm">{playing?.location ?? "Unknown network"} · {playing?.metadata?.bitrateKbps ?? "Unknown"} kbps</Text><Text size="sm">Video direct: {String(playing?.metadata?.transcoding?.isVideoDirect ?? "unknown")}</Text><Text size="sm">Audio direct: {String(playing?.metadata?.transcoding?.isAudioDirect ?? "unknown")}</Text></Stack>})}>Session details</Button></Stack></Card>; })}</SimpleGrid>
    {!query.isPending && !query.error && query.data?.configured !== false && rows.length === 0 && <Text c="dimmed">No active media sessions.</Text>}
    {query.data?.configured === false && <Text c="dimmed" size="sm">Bind a media server integration to show now-playing sessions.</Text>}
  </Stack>;
}

files.types.ts:
export type Camera = {name:string;path:string};
export type MediaOptions = {title:string;showSessions:boolean;cameras:Camera[];imageCount:number;snapshotInterval:number};
export interface GalleryItem {kind:"camera"|"immich";id:string;name:string;takenAt?:string;}
export type GalleryImageInput = Pick<GalleryItem,"kind"|"id">;
export interface ImmichAsset {id:string;originalFileName?:string;localDateTime?:string;fileCreatedAt?:string;}
export interface MediaSession {sessionId:string;sessionName:string;user:{username:string};currentlyPlaying:{name:string;episodeName?:string|null;location:"lan"|"wan"|null;playback:{state:"playing"|"paused"|"buffering"|null;positionMs:number|null;durationMs:number|null};metadata:{bitrateKbps:number|null;transcoding:{isVideoDirect:boolean;isAudioDirect:boolean}}|null}|null;}
export interface MediaSessions {data:MediaSession[];configured?:boolean;}
